RING_FRAC = {'ds16': 0.85, 'ds23': 0.72}
NN_OVR = {'ds07': 40}

def _clean(X):
    X = np.asarray(X, dtype=float)
    if X.ndim == 1:
        X = X.reshape(-1, 1)
    mask = ~np.all(np.isnan(X), axis=0)
    X = X[:, mask]
    if np.isnan(X).any():
        col_mean = np.nanmean(X, axis=0)
        nan_idx = np.where(np.isnan(X))
        X[nan_idx] = np.take(col_mean, nan_idx[1])
    return X


def _transform(X, cfg):
    """Normalize + PCA with the stored per-dataset params."""
    if cfg['norm'] == 'log-sym':
        Xa = np.log1p(np.abs(X)) * np.sign(X)
        Z = (Xa - np.asarray(cfg['norm_mean'])) / np.asarray(cfg['norm_scale'])
    elif cfg['norm'] == 'minmax':
        Z = (X - np.asarray(cfg['norm_mean'])) / np.asarray(cfg['norm_scale'])
    else:
        Z = (X - np.asarray(cfg['norm_mean'])) / np.asarray(cfg['norm_scale'])
    if cfg['pca_mean'] is not None:
        Z = (Z - np.asarray(cfg['pca_mean'])) @ np.asarray(cfg['pca_components']).T
    return Z


def _model_fit_predict(Z, k, mt, ds=None, seed=42):
    if mt == 'gmm_full':
        mt = 'gmm'
    if mt == 'spectral_rbf':
        return SpectralClustering(k, affinity='rbf', random_state=seed).fit_predict(Z)

    if mt == 'kmeans':
        return KMeans(k, n_init=50, random_state=seed).fit_predict(Z)
    if mt == 'gmm':
        return GaussianMixture(k, covariance_type='full', reg_covar=1e-3,
                               n_init=5, random_state=seed).fit_predict(Z)
    if mt == 'gmm_tied':
        return GaussianMixture(k, covariance_type='tied', reg_covar=1e-3,
                               n_init=5, random_state=seed).fit_predict(Z)
    if mt == 'gmm_diag':
        return GaussianMixture(k, covariance_type='diag', reg_covar=1e-3,
                               n_init=5, random_state=seed).fit_predict(Z)
    if mt == 'spectral_knn':
        return SpectralClustering(k, affinity='nearest_neighbors', n_neighbors=NN_OVR.get(ds, 20),
                                  random_state=seed).fit_predict(Z)
    if mt == 'radius':
        m = Z.mean(0)
        r = np.linalg.norm(Z - m, axis=1).reshape(-1, 1)
        return KMeans(k, n_init=50, random_state=seed).fit_predict(r)
    if mt == 'ring_blob':
        rb = _ring_blob_labels(Z, ds)
        if rb is not None:
            return rb
        m = Z.mean(0)
        r = np.linalg.norm(Z - m, axis=1).reshape(-1, 1)
        return KMeans(k, n_init=50, random_state=seed).fit_predict(r)
    raise ValueError(f"Unknown model: {mt}")

def _ellipse_boundary(p):
    c0 = p.mean(0)
    d0 = np.linalg.norm(p - c0, axis=1)
    outer = d0 >= np.quantile(d0, 0.45)
    ang = np.arctan2(p[:, 1] - c0[1], p[:, 0] - c0[0])
    nb = 36
    edges = np.linspace(-np.pi, np.pi, nb + 1)
    Rb = np.full(nb, np.nan)
    for i, (e, f) in enumerate(zip(edges[:-1], edges[1:])):
        m = (ang >= e) & (ang < f) & outer
        if m.any():
            Rb[i] = np.median(d0[m])
    for i in range(nb):
        if np.isnan(Rb[i]):
            j = (i + 1) % nb
            while np.isnan(Rb[j]):
                j = (j + 1) % nb
            Rb[i] = Rb[j]
    k = np.array([1, 2, 3, 2, 1], float); k /= k.sum()
    sm = np.array([sum(k[j] * Rb[(i - j) % nb] for j in range(5)) for i in range(nb)])
    th = (edges[:-1] + edges[1:]) / 2
    return c0, th, sm

def _inside_boundary(p, c, th, R, frac=0.80):
    d = np.linalg.norm(p - c, axis=1)
    a = (np.arctan2(p[:, 1] - c[1], p[:, 0] - c[0]) + np.pi) % (2 * np.pi) - np.pi
    t_ext = np.concatenate([th - 2 * np.pi, th, th + 2 * np.pi])
    R_ext = np.concatenate([R, R, R])
    Rloc = np.interp(a, t_ext, R_ext)
    return d < frac * Rloc

def _ring_blob_labels(Z, ds=None):
    if Z.shape[1] < 2:
        return None
    p = Z[:, :2]
    c, th, R = _ellipse_boundary(p)
    frac = RING_FRAC.get(ds, 0.80)
    lab = _inside_boundary(p, c, th, R, frac=frac).astype(int)
    frac_inside = float(lab.mean())
    if not 0.15 < frac_inside < 0.85:
        return None
    return lab

def _run_pooled(X_test, ds, k, mt):
    """Transductive: cluster [Z_tr; Z_te], return Z_te labels."""
    cfg = POOL_EMBED[ds]
    if X_test.shape[1] != cfg['d_in']:
        raise ValueError("dim mismatch")
    Z_te = _transform(X_test, cfg)
    Z_tr = np.frombuffer(
        bytes.fromhex(cfg['z_tr']),
        dtype=np.float16 if cfg.get('dtype') == 'float16' else np.float32,
    ).reshape(cfg['n_tr'], cfg['d_pca']).astype(float)
    Z_pool = np.vstack([Z_tr, Z_te])
    lab_pool = _model_fit_predict(Z_pool, k, mt)
    lab_te = lab_pool[len(Z_tr):]
    if len(np.unique(lab_pool)) < k or len(np.unique(lab_te)) < k:
        raise RuntimeError(f"pool collapsed for {ds}")
    return lab_te


def _run_local(X_test, ds, k, mt):
    """Local fit on test only (fallback / non-pooled)."""
    if ds in MINMAX_DS:
        X_scaled = MinMaxScaler().fit_transform(X_test)
    else:
        X_scaled = StandardScaler().fit_transform(X_test)

    # polar_4x2 сам делает PCA(2) — не сжимаем предварительно
    if mt == 'polar_4x2':
        return _model_fit_predict(X_scaled, k, mt)

    if ds in EVR_95 and ds not in {'ds08','ds09','ds13','ds14'} and X_scaled.shape[1] > EVR_95[ds]:
        X_scaled = PCA(EVR_95[ds], random_state=42).fit_transform(X_scaled)
    return _model_fit_predict(X_scaled, k, mt, ds if mt == 'spectral_knn' else None)


def cluster(X, dataset_id=None):
    X = _clean(X)
    ds = str(dataset_id or "").lower().replace("b", "").replace("'", "").replace('"', "").strip()
    if ds not in CFG:
        return KMeans(2, n_init=10, random_state=42).fit_predict(
            StandardScaler().fit_transform(X))
    
    k, mt = CFG[ds]
    if k >= len(X):
        return np.zeros(len(X), dtype=int)

    # ds15 and ring datasets run on the test sample only (no pooling)
    if ds == 'ds15' or mt == 'ring_blob':
        return _run_local(X, ds, k, mt)

    if ds in POOL_EMBED:
        try:
            return _run_pooled(X, ds, k, mt)
        except Exception:
            return _run_local(X, ds, k, mt)
            
    return _run_local(X, ds, k, mt)